local MournToweRewardPopup = Class("MournToweRewardPopup")
local ActivityMournUtils = import('Game.Activity.Mourn.ActivityMournUtils')

function MournToweRewardPopup:__init()
	self._activityId = 0
	self._allRewardId = {}
	self._finallyVo = {}
end

function MournToweRewardPopup:__delete()
	self._activityId = 0
	self._allRewardId = {}
	self._finallyVo = nil
end

function MournToweRewardPopup:OnFocus(focus)
	if focus then
		local currency = ActivityMournUtils.GetShowCurrency()
		if table.count(currency) > 0 then
			CfUtils.RefreshTopGoods(currency)
		end
	end
end

function MournToweRewardPopup:OnShow()
	--- @type Engine.Lib.CoWait
	local coWait = CoWait.Start():Coroutine(util.cs_generator(function()
		local id = ActivityMournUtils.GetMaxPassTowerId()
		local vo = QuestConfMgr:GetInstance():GetQuestVoById(id)
		if vo then
			self.ListContent:MovePanelToItemIndex(checkNumber(vo.storey), 100)
		end
	end))
	return coWait
end

function MournToweRewardPopup:Awake()
	local argument = self.controller.Argument.parameters
	if argument then
		self._activityId = checkNumber(argument.activityId)
	end
	
	if checkNumber(self._activityId) == 0 then
		return
	end
	
	self:InitData()
	self:FillSelf()
end

function MournToweRewardPopup:InitData()
	local t = clone(ActivityMournUtils.GetTowerLevelVos(self._activityId))
	self._finallyVo = t[#t]
	table.remove(t, table.count(t))
	self._allRewardId = t
end

function MournToweRewardPopup:FillSelf()
	self.ListContent:InitListView(table.count(self._allRewardId), Bind(self, self.OnGetCellByIndex))
	
	local scr = CfUtils.GetLuaScr(self.FixedCell, MournToweRewardPopUpCell)
	if scr then
		scr:Refresh(self._finallyVo)
	end
end

function MournToweRewardPopup:OnGetCellByIndex(listView, index)
	if index < 0 then
		return nil
	end
	
	local id = self._allRewardId[index + 1]
	local cell = listView:NewListViewItem("Cell")
	
	local scr = CfUtils.GetLuaScr(cell.gameObject, MournToweRewardPopUpCell)
	if scr then
		scr:Refresh(id)
	end
	
	return cell
end

